162	
163	func TestEvaluateUnknownProductAndMissingFaultCode(t *testing.T) {
164		s := newStore(t)
165		if err := s.SubmitRequest("rUnknown", "pMissing", "F"); err != nil {
166			t.Fatalf("submit: %v", err)
167		}
168		if _, err := s.Evaluate("rUnknown", nowOK); !errors.Is(err, ErrNotFound) {
169			t.Fatalf("unknown product: got %v, want ErrNotFound", err)
170		}
171		if err := s.SubmitRequest("rEmpty", "p1", ""); !errors.Is(err, ErrInvalidParam) {
172			t.Fatalf("empty fault code at submit: got %v", err)
173		}
174	}
175	
176	func TestReserveSuccessAndStockMath(t *testing.T) {
177		s := newStore(t)
178		c, err := s.Reserve("c1", "r1", "part1", 4, expiryOK, nowOK)
179		if err != nil {
180			t.Fatalf("reserve: %v", err)
181		}
182		if c.Quantity != 4 || c.Used != 0 || c.Unused() != 0+4 {
183			t.Fatalf("bad commitment: %+v", c)
184		}
185		// 实物库存不变，可承诺量下降。
186		st, err := s.PartStatus("part1", nowOK)
187		if err != nil {
188			t.Fatalf("part status: %v", err)
189		}
190		if st.PhysicalRemaining != 10 || st.ActiveOccupied != 4 || st.Committable != 6 {
191			t.Fatalf("stock math: phys=%d occupied=%d committable=%d", st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
192		}
193	}
194	
195	func TestReserveIneligibleAndUnknown(t *testing.T) {
196		s := newStore(t)
197		if err := s.SubmitRequest("rBad", "p1", "FAULTX"); err != nil {
198			t.Fatalf("submit: %v", err)
199		}
200		if _, err := s.Reserve("c1", "rBad", "part1", 1, expiryOK, nowOK); !errors.Is(err, ErrIneligible) {
201			t.Fatalf("ineligible reserve: got %v", err)
202		}
203		if _, err := s.Reserve("c2", "rMissing", "part1", 1, expiryOK, nowOK); !errors.Is(err, ErrNotFound) {
204			t.Fatalf("unknown request: got %v", err)
