236			t.Fatalf("reserve after full: got %v", err)
237		}
238	}
239	
240	func TestReserveIdempotentAndConflict(t *testing.T) {
241		s := newStore(t)
242		c1, err := s.Reserve("c1", "r1", "part1", 4, expiryOK, nowOK)
243		if err != nil {
244			t.Fatalf("reserve: %v", err)
245		}
246		// 相同编号相同内容重试：返回同一承诺，不重复占用。
247		c2, err := s.Reserve("c1", "r1", "part1", 4, expiryOK, nowOK)
248		if err != nil {
249			t.Fatalf("idempotent retry: %v", err)
250		}
251		if c2.ID != c1.ID || c2.Quantity != c1.Quantity {
252			t.Fatalf("retry returned different commitment: %+v vs %+v", c2, c1)
253		}
254		st, _ := s.PartStatus("part1", nowOK)
255		if st.ActiveOccupied != 4 {
256			t.Fatalf("retry double-occupied: %d", st.ActiveOccupied)
257		}
258	
259		// 换数量 / 换备件 / 换请求 / 换到期时刻 → 冲突。
260		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); !errors.Is(err, ErrConflict) {
261			t.Fatalf("conflict on quantity: got %v", err)
262		}
263		if _, err := s.Reserve("c1", "r1", "part2", 4, expiryOK, nowOK); !errors.Is(err, ErrConflict) {
264			t.Fatalf("conflict on part: got %v", err)
