11	// historyStore 构造一个带产品/备件/请求的仓库。
12	func historyStore(t *testing.T) *Store {
13		t.Helper()
14		s := NewStore()
15		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
16			t.Fatalf("register product: %v", err)
17		}
18		if err := s.RegisterPart("part1", 10); err != nil {
19			t.Fatalf("register part: %v", err)
20		}
21		if err := s.SubmitRequest("r1", "p1", "FAULTY"); err != nil {
22			t.Fatalf("submit request: %v", err)
23		}
24		return s
25	}
