27	func TestHistoryEmptyAndValidation(t *testing.T) {
28		s := historyStore(t)
29	
30		// 已知请求没有记录时返回空列表（非 nil）。
31		h, err := s.RequestHistory("r1")
32		if err != nil {
33			t.Fatalf("history: %v", err)
34		}
35		if h == nil || len(h) != 0 {
36			t.Fatalf("expected empty non-nil history, got %v", h)
37		}
38	
39		// 空请求编号 → ErrInvalidParam。
40		if _, err := s.RequestHistory(""); !errors.Is(err, ErrInvalidParam) {
41			t.Fatalf("empty request id: got %v", err)
42		}
43		// 未知请求 → ErrNotFound。
44		if _, err := s.RequestHistory("rMissing"); !errors.Is(err, ErrNotFound) {
45			t.Fatalf("unknown request: got %v", err)
46		}
47	}
