49	func TestHistorySuccessRecord(t *testing.T) {
50		s := historyStore(t)
51		c, err := s.Reserve("c1", "r1", "part1", 4, expiryOK, nowOK)
52		if err != nil {
53			t.Fatalf("reserve: %v", err)
54		}
55		h, err := s.RequestHistory("r1")
56		if err != nil {
57			t.Fatalf("history: %v", err)
58		}
59		if len(h) != 1 {
60			t.Fatalf("history len = %d, want 1", len(h))
61		}
62		rec := h[0]
63		if rec.Seq != 1 || !rec.Success || rec.Error != "" {
64			t.Fatalf("bad success marker: seq=%d success=%v error=%q", rec.Seq, rec.Success, rec.Error)
65		}
66		if rec.CommitID != c.ID || rec.PartID != "part1" || rec.Quantity != 4 {
67			t.Fatalf("bad submission fields: %+v", rec)
68		}
69		if !rec.Expiry.Equal(expiryOK) || !rec.Now.Equal(nowOK) {
70			t.Fatalf("bad times: expiry=%v now=%v", rec.Expiry, rec.Now)
71		}
72		// 资格依据快照。
73		if rec.Eligibility == nil {
74			t.Fatal("expected eligibility snapshot")
75		}
76		if !rec.Eligibility.Eligible || rec.Eligibility.PurchaseTime != t0 ||
77			rec.Eligibility.WarrantyDays != 30 || rec.Eligibility.WarrantyExpiry != t0.Add(30*day) ||
78			rec.Eligibility.Excluded || len(rec.Eligibility.Reasons) != 0 {
79			t.Fatalf("bad eligibility snapshot: %+v", rec.Eligibility)
80		}
81		// 库存依据：处理前实物 10、占用 0、可承诺 10。
82		if rec.StockBasis == nil {
83			t.Fatal("expected stock basis snapshot")
84		}
85		if rec.StockBasis.PhysicalRemaining != 10 || rec.StockBasis.ActiveOccupied != 0 ||
86			rec.StockBasis.Committable != 10 {
87			t.Fatalf("bad stock basis: %+v", rec.StockBasis)
88		}
89	}
