91	func TestHistoryIneligibleRecord(t *testing.T) {
92		s := historyStore(t)
93		if err := s.SubmitRequest("rBad", "p1", "FAULTX"); err != nil {
94			t.Fatalf("submit: %v", err)
95		}
96		// 第 31 天：过保且除外，两项原因都保留。
97		if _, err := s.Reserve("c1", "rBad", "part1", 1, expiryOK, t0.Add(31*day)); !errors.Is(err, ErrIneligible) {
98			t.Fatalf("reserve: got %v", err)
99		}
100		h, _ := s.RequestHistory("rBad")
101		if len(h) != 1 {
102			t.Fatalf("history len = %d, want 1", len(h))
103		}
104		rec := h[0]
105		if rec.Success || rec.Error != HistoryErrorIneligible {
106			t.Fatalf("bad error category: success=%v error=%q", rec.Success, rec.Error)
107		}
108		if rec.Eligibility == nil {
109			t.Fatal("expected eligibility snapshot for ineligible record")
110		}
111		if rec.Eligibility.Eligible || !rec.Eligibility.Excluded {
112			t.Fatalf("expected ineligible+excluded: %+v", rec.Eligibility)
113		}
114		got := map[RejectionReason]bool{}
115		for _, r := range rec.Eligibility.Reasons {
116			got[r] = true
117		}
118		if !got[ReasonWarrantyExpired] || !got[ReasonFaultExcluded] {
119			t.Fatalf("reasons = %v, want both warranty_expired and fault_code_excluded", rec.Eligibility.Reasons)
120		}
121		// 库存依据仍保留（备件存在）。
122		if rec.StockBasis == nil || rec.StockBasis.Committable != 10 {
123			t.Fatalf("stock basis: %+v", rec.StockBasis)
124		}
125	}
