368	func TestHistoryConcurrentReservesMatchResults(t *testing.T) {
369		s := historyStore(t)
370		const n = 30
371		var wg sync.WaitGroup
372		var mu sync.Mutex
373		success, failed := 0, 0
374		for i := 0; i < n; i++ {
375			wg.Add(1)
376			go func(i int) {
377				defer wg.Done()
378				_, err := s.Reserve(fmt.Sprintf("c%02d", i), "r1", "part1", 1, expiryOK, nowOK)
379				mu.Lock()
380				defer mu.Unlock()
381				if err == nil {
382					success++
383				} else if errors.Is(err, ErrInsufficientStock) {
384					failed++
385				} else {
386					t.Errorf("unexpected error: %v", err)
387				}
388			}(i)
389		}
390		wg.Wait()
391		if success != 10 || failed != 20 {
392			t.Fatalf("success=%d failed=%d, want 10/20", success, failed)
393		}
394		h, _ := s.RequestHistory("r1")
395		if len(h) != n {
396			t.Fatalf("history len = %d, want %d (every submission recorded)", len(h), n)
397		}
398		succ, fail := 0, 0
399		for _, rec := range h {
400			if rec.Success {
401				succ++
402				// 成功记录的库存依据必须反映处理前可承诺量 >= 1。
403				if rec.StockBasis == nil || rec.StockBasis.Committable < 1 {
404					t.Fatalf("success record with bad stock basis: %+v", rec)
405				}
406			} else {
407				fail++
408				if rec.Error != HistoryErrorInsufficientStock {
409					t.Fatalf("unexpected failure category: %q", rec.Error)
410				}
411				// 失败记录的库存依据必须反映处理前可承诺量 < 1。
412				if rec.StockBasis == nil || rec.StockBasis.Committable >= 1 {
413					t.Fatalf("failure record with bad stock basis: %+v", rec)
414				}
415			}
416		}
417		if succ != 10 || fail != 20 {
418			t.Fatalf("history success/fail = %d/%d, want 10/20", succ, fail)
419		}
420		// 序号严格递增。
421		for i, rec := range h {
422			if rec.Seq != i+1 {
423				t.Fatalf("record %d seq = %d", i, rec.Seq)
424			}
425		}
426	}
