	}
	if h[0].Success || h[0].Error != HistoryErrorInsufficientStock {
		t.Fatalf("first record should be failure: %+v", h[0])
	}
	if !h[1].Success || h[1].Error != "" {
		t.Fatalf("second record should be success: %+v", h[1])
	}
	// 承诺编号只被占用一次。
	st, _ := s.PartStatus("part1", nowOK)
