// 原样重试仍只取回旧结果，首次成功的资格与库存依据不被重试时刻覆盖。
func TestReserveRetryIgnoresLaterEligibilityAndStock(t *testing.T) {
	s := newStore(t)
	first, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK)
	if err != nil {
		t.Fatalf("reserve: %v", err)
	}
